def parse_diaspora_webfinger(document: str) -> Dict:
    import json, xml.etree.ElementTree as ET
    doc = document.strip()
    if doc.startswith('{') or doc.startswith('['):
        try:
            return json.loads(doc)
        except json.JSONDecodeError:
            pass
    # else parse XRD
    try:
        root = ET.fromstring(doc)
    except ET.ParseError:
        raise ValueError("Invalid webfinger document")
    ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
    subject = root.find('xrd:Subject', ns)
    subject_text = subject.text if subject is not None else None
    aliases = [a.text for a in root.findall('xrd:Alias', ns) if a.text]
    links = []
    for link in root.findall('xrd:Link', ns):
        rel = link.attrib.get('rel')
        type_ = link.attrib.get('type')
        href = link.attrib.get('href')
        links.append({'rel': rel, 'type': type_, 'href': href})
    return {'subject': subject_text, 'aliases': aliases, 'links': links}

