def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Ensure the parser has subparsers
    if not hasattr(self, 'parser'):
        raise AttributeError("The object does not have a 'parser' attribute.")
    subparsers = getattr(self.parser, '_subparsers', None)
    if subparsers is None:
        raise ValueError("The parser does not contain subparsers.")
    # Find the subparser for the given command name
    target_subparser = None
    for action in subparsers._actions:
        if isinstance(action, argparse._SubParsersAction):
            for name, subparser in action.choices.items():
                if name == command_name:
                    target_subparser = subparser
                    break
        if target_subparser:
            break
    if target_subparser is None:
        raise ValueError(f"Command '{command_name}' not found in subparsers.")
    # Collect all option strings from the subparser's actions
    option_specs = []
    for action in target_subparser._actions:
        # Skip positional arguments (those without option strings)
        if action.option_strings:
            option_specs.extend(action.option_strings)
    return option_specs

